			}
		}

		// Erlang has no top-level call expressions: everything outside function
		// bodies is a module attribute, and attribute payloads like
		// `-spec name(...)` or `-export([...])` are declarations that would
		// register as bogus file->function call sites. OCaml is skipped for
		// the mirror-image reason: expression code lives in `let` bindings
		// (extracted as symbols and scanned by the dedicated OCaml pass), so
		// what remains at top level is declarations — opens, type definitions,


### capability-tests
type Config struct{}
`)
	writeFile(t, repo, "beta/config.go", `package beta

type Config struct{}
`)
	writeFile(t, repo, "app/use.go", `package app

import cfg "example.com/review/beta"

func Use(value *cfg.Config) {}
`)

	snapshot, err := BuildProviderSnapshot(t.Context(), repo, "test-version")
	if err != nil {
		t.Fatal(err)
	}

	var typeEdges []RelationRecord
	for _, r := range snapshot.Relations {
		if r.Type != "USES_TYPE" && r.Type != "PARAM_TYPE" && r.Type != "RETURNS_TYPE" {
			continue
		}
		if !strings.Contains(r.FromID, "function:Use") || !strings.HasSuffix(r.ToID, ":Config") {
			continue
		}
		typeEdges = append(typeEdges, r)
	}
	if len(typeEdges) == 0 {
		t.Fatal("qualified imported Config produced no type edges")
	}
	for _, r := range typeEdges {
