 11	// astParameterNamesFor parses src and returns the parameter names of the first
 12	// callable the walk reaches, mirroring how the parser reaches an entity node.
 13	func astParameterNamesFor(t *testing.T, path, src string) ([]string, bool) {
 14		t.Helper()
 15		spec, ok := languageForPath(path)
 16		if !ok {
 17			t.Fatalf("no language spec for %s", path)
 18		}
 19		parser := sitter.NewParser()
 20		defer parser.Close()
 21		parser.SetLanguage(spec.grammar)
 22		tree, err := parser.ParseCtx(context.Background(), nil, []byte(src))
 23		if err != nil {
 24			t.Fatalf("parse %s: %v", path, err)
 25		}
 26		defer tree.Close()
 27	
 28		var names []string
 29		var known bool
 30		var walk func(node *sitter.Node)
 31		walk = func(node *sitter.Node) {
 32			if known || !validNode(node) {
 33				return
 34			}
 35			if got, ok := astParameterNames(node, []byte(src)); ok && len(got) > 0 {
 36				names, known = got, true
 37				return
 38			}
 39			for index := 0; index < int(node.NamedChildCount()); index++ {
 40				walk(node.NamedChild(index))
 41			}
 42		}
 43		walk(tree.RootNode())
 44		return names, known
 45	}
