 49	// on every comma and takes the first whitespace-delimited token, so it reported
 50	// a type as the parameter name in every type-first language (Java's
 51	// `check(String token)` yielded `String`) and leaked nested punctuation into the
 52	// list. Each case below is one of the shapes that got wrong.
 53	func TestASTParameterNamesAcrossGrammars(t *testing.T) {
 54		for _, testCase := range []struct {
 55			name string
 56			path string
 57			src  string
 58			want []string
 59		}{
 60			{
 61				name: "go receiver excluded from the list but kept as an input",
 62				path: "a.go",
 63				src:  "package p\nfunc (c *Client) Do(ctx Context, name, urlStr string, opts map[string]int) error { return nil }\n",
 64				want: []string{"c", "ctx", "name", "urlStr", "opts"},
 65			},
 66			{
 67				name: "python keeps both spellings of a splat",
 68				path: "a.py",
 69				src:  "def f(a, b=1, c: int = 2, *args, **kw):\n    pass\n",
 70				want: []string{"a", "b", "c", "args", "*args", "kw", "**kw"},
 71			},
 72			{
 73				name: "rust skips the self parameter",
 74				path: "a.rs",
 75				src:  "fn f(&self, a: u8, b: Vec<(u8, u8)>) -> u8 { a }\n",
 76				want: []string{"a", "b"},
 77			},
 78			{
 79				name: "java type-first parameters name the binding, not the type",
 80				path: "a.java",
 81				src:  "class C { void m(int a, Map<String, Integer> b, String... c) {} }\n",
 82				want: []string{"a", "b", "c"},
 83			},
 84			{
 85				name: "zig anonymous struct parameter contributes no field names",
 86				path: "a.zig",
 87				src:  "fn caller(b: *Build, options: struct { scripts: u8, git_commit: u8 }) void {}\n",
 88				want: []string{"b", "options"},
 89			},
 90			{
 91				name: "c declarator unwraps pointer and function layers",
 92				path: "a.c",
 93				src:  "int f(int a, char *b, void (*cb)(int)) { return a; }\n",
 94				want: []string{"a", "b", "cb"},
 95			},
 96			{
 97				name: "csharp params array is not mistaken for a parameter",
 98				path: "a.cs",
 99				src:  "class C { void M(int a, Dictionary<string, int> b, params int[] c) {} }\n",
100				want: []string{"a", "b", "c"},
101			},
102			{
103				name: "php strips the sigil and keeps the variadic spelling",
104				path: "a.php",
105				src:  "<?php function f($a, int $b = 1, ...$c) {} ?>\n",
106				want: []string{"a", "b", "c", "...c"},
107			},
108			{
109				name: "kotlin default value expression is not a parameter",
110				path: "a.kt",
111				src:  "fun f(a: Int, b: Map<String, Int> = mapOf()) {}\n",
112				want: []string{"a", "b"},
113			},
114			{
115				name: "swift external label yields to the internal name",
116				path: "a.swift",
117				src:  "func f(_ a: Int, label b: [String: Int]) {}\n",
118				want: []string{"a", "b"},
119			},
120			{
121				name: "ruby splat and block parameters",
122				path: "a.rb",
123				src:  "def f(a, b = 1, *c, **d)\nend\n",
124				want: []string{"a", "b", "c", "*c", "d", "**d"},
125			},
126			{
127				name: "dart type-first parameters",
128				path: "a.dart",
129				src:  "int f(int a, int b) => a;\n",
130				want: []string{"a", "b"},
131			},
132		} {
133			t.Run(testCase.name, func(t *testing.T) {
134				got, known := astParameterNamesFor(t, testCase.path, testCase.src)
135				if !known {
136					t.Fatalf("expected the grammar to expose a parameter list")
137				}
138				if !reflect.DeepEqual(got, testCase.want) {
139					t.Fatalf("parameter names: got %v want %v", got, testCase.want)
140				}
141			})
142		}
143	}
144	
145	// TestASTParameterNamesDeclinesUnknownShapes keeps the fallback honest: Elixir
146	// models `def f(a, b)` as a macro call with no parameter list, and reporting an
147	// empty list as authoritative there would suppress the signature regex that
148	// still finds names.
149	func TestASTParameterNamesDeclinesUnknownShapes(t *testing.T) {
150		if _, known := astParameterNamesFor(t, "a.ex", "def f(a, b) do\nend\n"); known {
151			t.Fatalf("expected Elixir to fall through to the signature regex")
152		}
153	}
154	
155	// TestASTParameterNamesRejectsSignatureRegexArtifacts is the regression this
156	// work exists for: the regex invented parameters out of struct fields and a
157	// stray closing brace, and those names then fabricated DATA_FLOWS edges
158	// asserting a caller parameter was forwarded when the identifier was a
159	// module-level constant.
160	func TestASTParameterNamesRejectsSignatureRegexArtifacts(t *testing.T) {
161		const zig = "fn caller(b: *Build, options: struct { scripts: u8, git_commit: u8, }) void {}\n"
162		regexNames := parameterNames("fn caller(b: *Build, options: struct { scripts: u8, git_commit: u8, }) void")
163		for _, artifact := range []string{"}", "git_commit"} {
164			if !regexNames[artifact] {
165				t.Fatalf("expected the signature regex to invent %q (the bug under test)", artifact)
166			}
167		}
168		got, known := astParameterNamesFor(t, "a.zig", zig)
169		if !known {
170			t.Fatalf("expected Zig parameters to come from the parse tree")
171		}
172		for _, artifact := range []string{"}", "git_commit"} {
173			for _, name := range got {
174				if name == artifact {
175					t.Fatalf("parse tree extraction leaked the regex artifact %q: %v", artifact, got)
176				}
177			}
178		}
179	}

